import { DurableObject } from 'cloudflare:workers';
import { Lifecycle } from 'agents/lifecycle';
import { MCPClientManager } from 'agents/mcp/client';

const TOOLS_SERVER_ID = 'tools';

// A plain Durable Object (not an Agent). Our other Workers call listTools() over RPC.
export class ToolGateway extends DurableObject {
  // The manager persists registered servers in this object's SQLite storage and
  // restores them in its onStart hook, so the connection survives eviction.
  mcp = new MCPClientManager('tool-gateway', '1.0.0');
  lifecycle = Lifecycle.install(this).use(this.mcp);

  async listTools() {
    // Native RPC bypasses fetch, so start the lifecycle (and restore persisted
    // connections) explicitly.
    await this.lifecycle.start();

    if (!this.mcp.mcpConnections[TOOLS_SERVER_ID]) {
      await this.mcp.registerServer(TOOLS_SERVER_ID, {
        url: this.env.TOOLS_MCP_URL,
        name: 'tools',
      });
      const result = await this.mcp.connectToServer(TOOLS_SERVER_ID);
      if (result.state === 'failed') {
        throw new Error(`Failed to connect to MCP server: ${result.error}`);
      }
      await this.mcp.discoverIfConnected(TOOLS_SERVER_ID);
    }

    // After a wake, restored connections may still be connecting/discovering.
    await this.mcp.waitForConnections();
    return this.mcp.listTools({ serverId: TOOLS_SERVER_ID });
  }
}

